package com.propverse;
import com.propverse.ui.DashboardFrame;import com.propverse.service.AuthenticationService;import javax.swing.*;import java.awt.*;
public class Main {public static void main(String[] args){SwingUtilities.invokeLater(()->new Login().setVisible(true));}static class Login extends JFrame{private final JTextField user=new JTextField(18);private final JPasswordField pass=new JPasswordField(18);Login(){super("PropVerse Login");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(390,250);setLocationRelativeTo(null);JPanel p=new JPanel(new GridLayout(0,2,8,12));p.setBorder(BorderFactory.createEmptyBorder(22,22,22,22));p.add(new JLabel("Username"));p.add(user);p.add(new JLabel("Password"));p.add(pass);JButton login=new JButton("Login"),setup=new JButton("Create first administrator");p.add(login);p.add(setup);add(p);login.addActionListener(e->authenticate());setup.addActionListener(e->create());}void authenticate(){try{if(new AuthenticationService().login(user.getText(),pass.getPassword())){dispose();new DashboardFrame(x->new Login().setVisible(true)).setVisible(true);}else JOptionPane.showMessageDialog(this,"Invalid username or password.");}catch(Exception e){JOptionPane.showMessageDialog(this,"Cannot sign in: "+e.getMessage());}}void create(){try{new AuthenticationService().createAdmin(user.getText(),pass.getPassword());JOptionPane.showMessageDialog(this,"Administrator created. Sign in now.");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}}}
